// Banco de questoes - Historia (Cap. 6 - Uma dadiva do Nilo) - 5o ano - prova 18/08
window.BANCO = window.BANCO || {};
window.BANCO.historia = [
{n:"f",t:"Novas moradias",q:"O que eram os grupos nômades?",a:["Grupos que mudavam de lugar em busca de comida e água","Grupos que moravam sempre na mesma cidade","Grupos que viviam apenas dentro de barcos","Grupos que construíam pirâmides de pedra"],c:0,e:"Nômades não tinham morada fixa: quando a comida acabava num lugar, eles se mudavam para outro, como quem vive sempre de mochila nas costas."},
{n:"f",t:"Novas moradias",q:"O que é sedentarização?",a:["Quando um grupo viaja o tempo todo","Quando um grupo passa a morar fixo em um só lugar","Quando um grupo constrói barcos para pescar","Quando um grupo aprende a escrever"],c:1,e:"Sedentarizar-se é criar raízes: o grupo para de vagar e passa a viver sempre no mesmo lugar, cuidando de plantações e moradias."},
{n:"f",t:"Novas moradias",q:"O que os grupos humanos mais procuravam ao escolher um lugar para morar?",a:["Ouro e pedras preciosas","Montanhas altas e frias","Água e terra fértil","Areia e vento forte"],c:2,e:"Sem água ninguém vive e sem terra boa nada cresce. Por isso as margens dos rios eram os lugares preferidos para morar."},
{n:"f",t:"Novas moradias",q:"Às margens de qual rio os antigos egípcios se fixaram?",a:["Amazonas","Tigre","São Francisco","Nilo"],c:3,e:"O rio Nilo atravessa o Egito e foi ali, nas suas margens férteis, que os egípcios construíram suas aldeias e cidades."},
{n:"f",t:"Novas moradias",q:"Um grupo que mora sempre no mesmo lugar é chamado de...",a:["nômade","viajante","sedentário","explorador"],c:2,e:"Sedentário é quem tem endereço fixo, como a gente. O contrário é o nômade, que vive mudando de lugar."},
{n:"f",t:"Novas moradias",q:"Por que morar perto de um rio era uma boa ideia?",a:["Porque o rio protegia do frio","Porque perto do rio não existiam animais","Porque o rio afastava as chuvas","Porque havia água para beber, plantar e pescar"],c:3,e:"O rio dava quase tudo: água para beber, peixes para comer e terra molhada para plantar. Era como um mercado que nunca fechava. 😄"},
{n:"f",t:"Novas moradias",q:"Antes de se fixarem, como os grupos nômades conseguiam alimento?",a:["Caçando, pescando e coletando frutos","Comprando em mercados","Plantando grandes roças","Criando gado em fazendas"],c:0,e:"Os nômades pegavam o que a natureza oferecia: caça, pesca e frutos. Quando o alimento acabava, partiam para outro lugar."},
{n:"f",t:"Novas moradias",q:"O que é uma terra fértil?",a:["Uma terra cheia de pedras","Uma terra boa para plantar, onde as sementes crescem bem","Uma terra sempre coberta de gelo","Uma terra onde nada consegue crescer"],c:1,e:"Terra fértil é terra forte, cheia de nutrientes. Nela, a semente vira planta com facilidade, como num canteiro bem adubado."},
{n:"f",t:"Novas moradias",q:"Qual atividade ajudou os grupos humanos a pararem de se mudar de lugar?",a:["A caça de animais grandes","A agricultura","A construção de barcos","A pintura nas cavernas"],c:1,e:"Quem planta precisa esperar a colheita. Assim, a agricultura fez os grupos ficarem no mesmo lugar por muito tempo, até virarem aldeias."},
{n:"f",t:"Novas moradias",q:"Depois de se fixarem perto do Nilo, o que os grupos construíram?",a:["Moradias fixas e aldeias, que depois viraram cidades","Casas sobre rodas para seguir viajando","Cavernas no alto das montanhas geladas","Barcos enormes para morar no mar"],c:0,e:"Morando fixo, valia a pena construir casas duradouras. As aldeias cresceram e, com o tempo, se transformaram em cidades."},
{n:"f",t:"Egito Antigo",q:"Em que continente fica o Egito?",a:["Europa","Ásia","América do Sul","África"],c:3,e:"O Egito fica no nordeste da África. Mesmo sendo vizinho da Ásia, suas terras estão no continente africano."},
{n:"f",t:"Egito Antigo",q:"Em que parte da África fica o Egito?",a:["No sul","No centro","No nordeste","No extremo oeste"],c:2,e:"Olhe o mapa da África: o Egito fica lá em cima, do lado direito — ou seja, no nordeste do continente."},
{n:"f",t:"Egito Antigo",q:"Qual deserto cobre a maior parte das terras ao redor do vale do Nilo?",a:["Atacama","Kalahari","Gobi","Saara"],c:3,e:"O Saara é o maior deserto quente do mundo e cerca o Egito. Por isso a vida se concentrava na faixa verde perto do Nilo."},
{n:"f",t:"Egito Antigo",q:"Quem escreveu que 'o Egito é uma dádiva do Nilo'?",a:["Champollion","Quéops","Heródoto","Anúbis"],c:2,e:"Heródoto era um estudioso grego que visitou o Egito. Para ele, sem o presente do rio Nilo, o Egito não existiria."},
{n:"f",t:"Egito Antigo",q:"O que as cheias do rio Nilo deixavam sobre a terra?",a:["Pedras enormes que atrapalhavam o plantio","Húmus, um adubo natural que fertilizava o solo","Sal que estragava as plantações","Areia seca vinda do deserto"],c:1,e:"Quando a água baixava, ficava uma camada escura chamada húmus ou limo, que funcionava como adubo. A terra ficava pronta para plantar!"},
{n:"f",t:"Egito Antigo",q:"O que é a cheia de um rio?",a:["Quando o rio sobe e transborda, alagando as margens","Quando o rio seca completamente","Quando o rio congela no inverno","Quando o rio muda de direção"],c:0,e:"Na cheia, o rio fica cheio de tanta água que invade as margens. No Egito, isso acontecia todo ano e era motivo de festa."},
{n:"f",t:"Egito Antigo",q:"Qual destes produtos os egípcios plantavam nas margens do Nilo?",a:["Café","Trigo","Milho","Cacau"],c:1,e:"Os egípcios plantavam trigo, cevada, linho e papiro. Café, milho e cacau só existiam em outras partes do mundo naquela época."},
{n:"f",t:"Egito Antigo",q:"Para que os egípcios usavam a planta do linho?",a:["Para construir pirâmides","Para alimentar os animais","Para fazer tecidos e roupas","Para fabricar espadas"],c:2,e:"Do linho saíam fios que viravam tecidos leves, ótimos para o calor do Egito. Até as faixas das múmias eram de linho!"},
{n:"f",t:"Egito Antigo",q:"O que os egípcios construíram para levar água do rio até as plantações?",a:["Pontes de madeira","Muralhas de pedra","Torres de vigia","Canais de irrigação"],c:3,e:"Os canais eram como caminhos de água: levavam a água do Nilo até plantações mais distantes. Isso se chama irrigação."},
{n:"f",t:"Egito Antigo",q:"Além da agricultura, o que mais o rio Nilo oferecia aos egípcios?",a:["Peixes e um caminho para os barcos","Ouro em suas águas","Proteção contra o calor","Madeira para construção"],c:0,e:"O Nilo era rio de pescar e de viajar: os barcos levavam pessoas e mercadorias de uma cidade a outra, como uma estrada de água."},
{n:"f",t:"Egito Antigo",q:"Na frase de Heródoto, o que significa a palavra 'dádiva'?",a:["Presente","Castigo","Mistério","Tempestade"],c:0,e:"Dádiva quer dizer presente. Heródoto quis dizer que o Egito ganhou do Nilo tudo o que precisava para existir."},
{n:"f",t:"Egito Antigo",q:"De quanto em quanto tempo aconteciam as cheias do Nilo?",a:["Uma vez por semana","Uma vez a cada dez anos","Duas vezes por mês","Uma vez por ano"],c:3,e:"As cheias eram anuais: aconteciam sempre na mesma época do ano. Os egípcios já esperavam por elas para organizar o plantio."},
{n:"f",t:"Egito Antigo",q:"O que é irrigação?",a:["Colher os frutos maduros","Levar água até as plantações","Espantar os pássaros da roça","Misturar areia na terra"],c:1,e:"Irrigar é dar de beber às plantas. Os egípcios usavam canais e diques para molhar a terra mesmo longe do rio."},
{n:"f",t:"Sociedade egípcia",q:"Quem ocupava o topo da sociedade egípcia?",a:["Os camponeses","Os comerciantes","O faraó","Os soldados"],c:2,e:"O faraó era o chefe supremo do Egito: ficava no topo da pirâmide social e todos deviam obedecê-lo."},
{n:"f",t:"Sociedade egípcia",q:"Para os egípcios, o faraó era considerado...",a:["um simples funcionário","um estrangeiro visitante","um deus vivo","um escriba aposentado"],c:2,e:"O povo acreditava que o faraó era um deus morando na Terra. Por isso seu poder era total e ninguém discutia suas ordens."},
{n:"f",t:"Sociedade egípcia",q:"Quem eram os escribas?",a:["Os profissionais que sabiam ler e escrever","Os guerreiros do exército do faraó","Os agricultores das margens do Nilo","Os construtores de barcos"],c:0,e:"Escriba era quem dominava a escrita, algo raríssimo na época. Eles anotavam impostos, colheitas e textos importantes."},
{n:"f",t:"Sociedade egípcia",q:"Qual grupo formava a maioria da população do Egito?",a:["Os sacerdotes","Os escribas","Os faraós","Os camponeses"],c:3,e:"A maior parte do povo egípcio era camponesa. Eles plantavam, colhiam e ainda trabalhavam nas grandes construções."},
{n:"f",t:"Sociedade egípcia",q:"Quem ficava na base da pirâmide social egípcia?",a:["Os sacerdotes","As pessoas escravizadas","Os artesãos","Os soldados"],c:1,e:"Na base ficavam os escravizados, obrigados a trabalhar sem liberdade. Quanto mais para baixo na pirâmide, menos direitos a pessoa tinha."},
{n:"f",t:"Sociedade egípcia",q:"Quem cuidava dos templos e das cerimônias religiosas?",a:["Os comerciantes","Os camponeses","Os soldados","Os sacerdotes"],c:3,e:"Os sacerdotes eram os responsáveis por agradar os deuses: cuidavam dos templos, das oferendas e dos rituais."},
{n:"f",t:"Sociedade egípcia",q:"Qual era o trabalho dos camponeses?",a:["Escrever documentos do governo","Cultivar a terra e ajudar nas grandes construções","Comandar o exército","Rezar nos templos pelos deuses"],c:1,e:"Os camponeses plantavam e colhiam. Na época das cheias, quando os campos ficavam alagados, muitos iam trabalhar nas obras do faraó."},
{n:"f",t:"Sociedade egípcia",q:"Como é chamado o desenho que mostra a organização da sociedade egípcia, com o faraó em cima?",a:["Pirâmide social","Mapa do tesouro","Linha do tempo","Círculo das famílias"],c:0,e:"Usamos uma pirâmide para mostrar essa sociedade: pouquíssima gente no topo, com muito poder, e muita gente embaixo, com pouco poder."},
{n:"f",t:"Sociedade egípcia",q:"Quem tinha como missão defender o Egito?",a:["Os escribas","Os artesãos","Os soldados","Os sacerdotes"],c:2,e:"Os soldados formavam o exército do faraó e protegiam o Egito de invasores."},
{n:"f",t:"Sociedade egípcia",q:"O que faziam os artesãos?",a:["Fabricavam objetos como vasos, joias e móveis","Cobravam os impostos do reino","Escreviam nos papiros do palácio","Comandavam os rituais religiosos"],c:0,e:"Artesão é quem faz coisas com as mãos: cerâmica, joias, sandálias, móveis. Eles vendiam ou trocavam o que produziam."},
{n:"f",t:"Sociedade egípcia",q:"O que faziam os comerciantes?",a:["Construíam as pirâmides sozinhos","Vendiam e trocavam mercadorias","Escolhiam o novo faraó","Mumificavam os mortos"],c:1,e:"Os comerciantes compravam, vendiam e trocavam produtos, como grãos, tecidos e objetos, dentro e fora do Egito."},
{n:"f",t:"Sociedade egípcia",q:"Como era o poder do faraó sobre o Egito?",a:["Dividido igualmente com os camponeses","Válido apenas dentro do palácio","Total: ele mandava em tudo e em todos","Limitado às decisões dos comerciantes"],c:2,e:"O faraó dava a palavra final sobre tudo: leis, guerras, construções e religião. Ninguém tinha mais poder do que ele."},
{n:"f",t:"Deuses do Nilo",q:"Como se chama a crença em vários deuses?",a:["Monoteísmo","Politeísmo","Ateísmo","Batismo"],c:1,e:"'Poli' quer dizer muitos. Os egípcios eram politeístas porque acreditavam em muitos deuses ao mesmo tempo."},
{n:"f",t:"Deuses do Nilo",q:"Como muitos deuses egípcios eram representados?",a:["Com corpo de animal e asas de pássaro","Apenas como seres humanos comuns","Como gigantes feitos de areia","Com corpo humano e cabeça de animal"],c:3,e:"Nas pinturas e estátuas, muitos deuses têm corpo de gente e cabeça de animal, como Hórus (falcão) e Anúbis (chacal)."},
{n:"f",t:"Deuses do Nilo",q:"Rá era o deus de quê?",a:["Da chuva","Da guerra","Do Sol","Dos peixes"],c:2,e:"Rá era o deus do Sol, um dos mais importantes do Egito. Os egípcios acreditavam que ele atravessava o céu todos os dias."},
{n:"f",t:"Deuses do Nilo",q:"Qual deus era representado com cabeça de falcão?",a:["Hórus","Osíris","Anúbis","Hathor"],c:0,e:"Hórus, o deus do céu, aparece com cabeça de falcão. Os olhos do falcão enxergam de longe, como um vigia do céu."},
{n:"f",t:"Deuses do Nilo",q:"Qual deus tinha cabeça de chacal e era ligado à mumificação?",a:["Anúbis","Hórus","Rá","Ísis"],c:0,e:"Anúbis, com sua cabeça de chacal, era o deus que cuidava da mumificação e acompanhava os mortos."},
{n:"f",t:"Deuses do Nilo",q:"Osíris era o deus de quê?",a:["Do Sol e das estrelas","Dos rios e dos peixes","Do mundo dos mortos","Do vento e das tempestades"],c:2,e:"Osíris reinava sobre o mundo dos mortos. Os egípcios acreditavam que ele recebia as pessoas depois que elas morriam."},
{n:"f",t:"Deuses do Nilo",q:"Onde os egípcios deixavam oferendas para os deuses?",a:["Nos mercados","Nos barcos","Nas escolas","Nos templos"],c:3,e:"Os templos eram considerados a casa dos deuses. Lá o povo levava alimentos e presentes como forma de agradecer e pedir proteção."},
{n:"f",t:"Deuses do Nilo",q:"O que eram as oferendas?",a:["Impostos pagos ao faraó","Presentes e alimentos dados aos deuses","Prêmios dos soldados vencedores","Brinquedos das crianças egípcias"],c:1,e:"Oferenda é um presente para agradar os deuses: frutas, pães, flores, perfumes. Era um jeito de agradecer e fazer pedidos."},
{n:"f",t:"Deuses do Nilo",q:"Ísis era...",a:["a capital do Egito","uma pirâmide de Gizé","um tipo de papiro","uma importante deusa egípcia"],c:3,e:"Ísis era uma das deusas mais amadas do Egito, esposa de Osíris e mãe de Hórus. Era vista como grande protetora."},
{n:"f",t:"Deuses do Nilo",q:"Os egípcios eram monoteístas ou politeístas?",a:["Politeístas, porque acreditavam em muitos deuses","Monoteístas, porque adoravam apenas Rá","Ateus, porque não seguiam religião nenhuma","Monoteístas, porque adoravam apenas o faraó"],c:0,e:"Com Rá, Osíris, Ísis, Hórus, Anúbis, Hathor e muitos outros, a religião egípcia tinha vários deuses: isso é politeísmo."},
{n:"f",t:"Deuses do Nilo",q:"Hathor era...",a:["um faraó famoso","uma deusa egípcia","um deserto da África","uma cidade às margens do Nilo"],c:1,e:"Hathor era uma deusa egípcia ligada à alegria, à música e ao amor, muito querida pelo povo."},
{n:"f",t:"Deuses do Nilo",q:"Para os egípcios, quem controlava a natureza, como o Sol e as cheias do rio?",a:["Os escribas","Os comerciantes","Os deuses","Os viajantes estrangeiros"],c:2,e:"Os egípcios acreditavam que os deuses controlavam tudo na natureza: o Sol nascer, o rio encher, as plantas crescerem."},
{n:"f",t:"Escrita hieroglífica",q:"Como se chama a escrita egípcia feita com desenhos e símbolos?",a:["Alfabética","Numérica","Hieroglífica","Cursiva"],c:2,e:"Os hieróglifos são os famosos desenhos-símbolos dos egípcios: pássaros, olhos, ondas e muitos outros sinais."},
{n:"f",t:"Escrita hieroglífica",q:"Em que material os egípcios escreviam, parecido com o nosso papel?",a:["Plástico","Papiro","Vidro","Tecido de lã"],c:1,e:"O papiro era feito de uma planta que crescia às margens do Nilo. Ele funcionava como o 'papel' dos egípcios."},
{n:"f",t:"Escrita hieroglífica",q:"Quem era o profissional especializado em escrever no Egito?",a:["O escriba","O sacerdote","O soldado","O artesão"],c:0,e:"Escrever era o trabalho do escriba. Ele passava anos estudando os símbolos para registrar tudo o que era importante."},
{n:"f",t:"Escrita hieroglífica",q:"Qual descoberta permitiu decifrar os hieróglifos?",a:["O túmulo de Tutancâmon","A Esfinge de Gizé","Um mapa antigo do deserto","A Pedra de Roseta"],c:3,e:"A Pedra de Roseta trazia o mesmo texto em escritas diferentes. Comparando-as, os estudiosos descobriram o que os hieróglifos significavam."},
{n:"f",t:"Escrita hieroglífica",q:"Quem conseguiu decifrar os hieróglifos estudando a Pedra de Roseta?",a:["Champollion","Heródoto","Quéops","Osíris"],c:0,e:"O francês Champollion estudou a Pedra de Roseta por anos até decifrar os hieróglifos. Graças a ele, hoje conseguimos ler textos egípcios."},
{n:"f",t:"Escrita hieroglífica",q:"Onde os hieróglifos costumavam ser gravados?",a:["Apenas em moedas de ouro","Nas paredes de templos e tumbas","Somente em barcos de pesca","Apenas em roupas de linho"],c:1,e:"Por ser uma escrita considerada sagrada, os hieróglifos apareciam principalmente em templos e tumbas, além dos papiros."},
{n:"f",t:"Escrita hieroglífica",q:"O que eram os hieróglifos?",a:["Moedas usadas no comércio","Danças em homenagem aos deuses","Desenhos e símbolos que formavam uma escrita","Barcos usados nas cheias"],c:2,e:"Cada hieróglifo é um desenho que representa um som ou uma ideia. Juntos, eles formavam a escrita dos egípcios."},
{n:"f",t:"Escrita hieroglífica",q:"De onde vinha o papiro usado para escrever?",a:["De uma pedra branca do deserto","Da pele curtida de crocodilos","Da lã de carneiros","De uma planta que crescia às margens do Nilo"],c:3,e:"O papiro é uma planta do Nilo. Suas tiras eram prensadas até virar folhas para escrever, parecidas com papel."},
{n:"f",t:"Escrita hieroglífica",q:"A escrita hieroglífica era considerada...",a:["proibida no Egito","uma invenção dos gregos","uma escrita sem nenhum valor","sagrada, ligada aos deuses"],c:3,e:"Os egípcios viam os hieróglifos como escrita dos deuses, por isso ela aparecia em lugares especiais como templos e tumbas."},
{n:"f",t:"Escrita hieroglífica",q:"Como eram vistos os escribas na sociedade egípcia?",a:["Eram tratados como escravizados","Eram expulsos das cidades","Eram muito valorizados e respeitados","Eram obrigados a virar soldados"],c:2,e:"Saber ler e escrever era raro e importante. Por isso os escribas tinham uma posição de destaque e muitos privilégios."},
{n:"f",t:"Escrita hieroglífica",q:"O que significa 'decifrar' uma escrita antiga?",a:["Descobrir o que os símbolos significam","Apagar os símbolos das pedras","Inventar símbolos novos","Copiar os símbolos sem entender"],c:0,e:"Decifrar é como resolver um quebra-cabeça: descobrir o som e o significado de cada símbolo até conseguir ler o texto. 🧩"},
{n:"f",t:"Mumificação",q:"Por que os egípcios mumificavam os mortos?",a:["Para economizar espaço nas cidades","Porque acreditavam na vida após a morte","Para estudar o corpo humano","Para assustar os inimigos"],c:1,e:"Os egípcios acreditavam que a vida continuava depois da morte. O corpo precisava estar conservado para a alma poder voltar a ele."},
{n:"f",t:"Mumificação",q:"O que é uma múmia?",a:["Uma estátua de pedra do faraó","Um corpo conservado e enrolado em faixas","Um tipo de deus egípcio","Uma pintura feita nas tumbas"],c:1,e:"A múmia é o corpo que passou pelo processo de conservação e foi enfaixado. Algumas múmias duram milhares de anos!"},
{n:"f",t:"Mumificação",q:"Onde a múmia era colocada depois de pronta?",a:["Em um sarcófago","Em um vaso canópico","Em um barco no rio","Em um templo aberto ao público"],c:0,e:"O sarcófago era como um caixão decorado, muitas vezes com o rosto da pessoa pintado na tampa."},
{n:"f",t:"Mumificação",q:"Para que serviam as pirâmides do Egito?",a:["Eram mercados cobertos","Eram escolas de escribas","Eram celeiros de trigo","Eram túmulos de faraós"],c:3,e:"As pirâmides eram túmulos gigantes construídos para guardar o corpo e os tesouros dos faraós."},
{n:"f",t:"Mumificação",q:"Onde ficam as famosas pirâmides de Quéops, Quéfren e Miquerinos?",a:["Em Roma, na Itália","Em Atenas, na Grécia","Em Gizé, no Egito","Em Bagdá, no Iraque"],c:2,e:"As três grandes pirâmides ficam em Gizé, no Egito, pertinho da Esfinge. São os túmulos dos faraós Quéops, Quéfren e Miquerinos."},
{n:"f",t:"Mumificação",q:"Que monumento egípcio tem corpo de leão e cabeça humana?",a:["O obelisco","A Pedra de Roseta","A Esfinge","O sarcófago dourado"],c:2,e:"A Esfinge de Gizé mistura a força do leão com a cabeça humana. Ela parece montar guarda diante das pirâmides."},
{n:"f",t:"Mumificação",q:"Onde eram guardados os órgãos retirados do corpo na mumificação?",a:["Nas cestas de papiro","Nos potes de mel","Nos baús de madeira do palácio","Nos vasos canópicos"],c:3,e:"Os órgãos eram colocados em potes especiais chamados vasos canópicos, que ficavam na tumba junto com a múmia."},
{n:"f",t:"Mumificação",q:"Qual material era usado para secar o corpo durante a mumificação?",a:["Açúcar de cana","Natrão, um tipo de sal","Areia comum do deserto","Azeite de oliva"],c:1,e:"O natrão é um sal que puxa a água do corpo, deixando-o sequinho para não apodrecer — parecido com o que o sal faz com o peixe seco."},
{n:"f",t:"Mumificação",q:"Depois de seco, o corpo era...",a:["enrolado em faixas de linho","pintado de azul","coberto de folhas de papiro","vestido com armadura de bronze"],c:0,e:"Para terminar, o corpo era enfaixado com muitas voltas de tecido de linho. É assim que imaginamos uma múmia!"},
{n:"f",t:"Mumificação",q:"O que era colocado nas tumbas junto com os mortos?",a:["Apenas areia do deserto","Objetos, alimentos e joias","Somente água do Nilo","Nada, as tumbas ficavam vazias"],c:1,e:"Os egípcios enterravam objetos queridos, comida e joias com o morto, acreditando que ele usaria tudo isso na outra vida."},
{n:"f",t:"Mumificação",q:"Para os egípcios, por que o corpo precisava ser conservado?",a:["Para ser exposto nos mercados","Para servir de estátua no templo","Para a alma poder reconhecê-lo e retornar a ele","Para os médicos estudarem depois"],c:2,e:"Na crença egípcia, a alma continuava viva e precisava do corpo. Se o corpo se estragasse, a alma ficaria sem a sua 'casa'."},
{n:"f",t:"Mumificação",q:"Qual é a maior das três pirâmides de Gizé?",a:["A de Miquerinos","A de Anúbis","A de Champollion","A de Quéops"],c:3,e:"A pirâmide de Quéops é a maior de Gizé. Anúbis é um deus e Champollion foi o estudioso que decifrou os hieróglifos — eles não têm pirâmides."},
{n:"m",t:"Novas moradias",q:"Por que os grupos nômades precisavam se mudar de tempos em tempos?",a:["Porque gostavam de conhecer praias novas","Porque eram obrigados pelo faraó","Porque os alimentos da região acabavam","Porque fugiam do frio da neve"],c:2,e:"Quando a caça, os frutos e a água de um lugar acabavam, o grupo precisava partir para sobreviver. Era mudança por necessidade, não por passeio."},
{n:"m",t:"Novas moradias",q:"Por que a agricultura fez os grupos humanos pararem de se mudar?",a:["Porque era preciso ficar no lugar esperando a plantação crescer","Porque plantar era proibido para quem viajava","Porque as sementes eram pesadas demais para carregar","Porque os animais passaram a viajar sozinhos"],c:0,e:"Quem planta hoje só colhe meses depois. Para não perder a colheita, o grupo precisava ficar por perto — e assim foi criando raízes."},
{n:"m",t:"Novas moradias",q:"Por que as margens do rio Nilo atraíram tantos grupos humanos?",a:["Porque lá nunca fazia calor","Porque o rio era cheio de ouro","Porque não existiam animais perigosos","Porque tinham água e terra fértil no meio de uma região desértica"],c:3,e:"Ao redor era só deserto, mas na beira do Nilo havia água e terra ótima para plantar. Era um oásis gigante!"},
{n:"m",t:"Novas moradias",q:"Qual é a principal diferença entre um grupo nômade e um sedentário?",a:["O nômade vive em cidades; o sedentário vive em barcos","O nômade muda de lugar sempre; o sedentário mora fixo","O nômade planta; o sedentário só caça","O nômade escreve; o sedentário desenha"],c:1,e:"É como comparar quem vive de mudança com quem tem endereço fixo. O nômade segue o alimento; o sedentário produz o alimento onde mora."},
{n:"m",t:"Novas moradias",q:"Um grupo que planta cevada, cria animais e constrói casas de tijolos de barro é um grupo...",a:["nômade, que muda sempre de lugar","sedentário, que vive fixo num lugar","de pescadores que moram em barcos","de viajantes do deserto"],c:1,e:"Plantar, criar animais e construir casas firmes são sinais de quem pretende ficar: esse grupo se fixou, ou seja, é sedentário."},
{n:"m",t:"Novas moradias",q:"Com o passar do tempo, o que aconteceu com as pequenas aldeias às margens do Nilo?",a:["Foram engolidas pela areia e sumiram","Foram todas abandonadas pelos moradores","Viraram florestas fechadas","Cresceram e deram origem a cidades"],c:3,e:"Com comida garantida, mais gente foi chegando e ficando. As aldeias foram crescendo até se tornarem cidades movimentadas."},
{n:"m",t:"Novas moradias",q:"Se um grupo de caçadores nômades não encontra mais animais numa região, o que ele provavelmente faz?",a:["Muda para outra região em busca de alimento","Constrói uma pirâmide no local","Espera dez anos no mesmo lugar","Começa a fabricar papiro"],c:0,e:"Para o nômade, a solução era simples: arrumar as coisas e partir para onde houvesse caça, frutos e água."},
{n:"m",t:"Novas moradias",q:"Por que era tão difícil viver no meio do deserto do Saara?",a:["Porque chove forte todos os dias","Porque o chão é coberto de gelo","Porque quase não há água nem plantas","Porque há rios demais atrapalhando o caminho"],c:2,e:"O deserto é quente de dia, frio de noite e quase sem água. Sem água não há plantação nem criação — viver ali era quase impossível."},
{n:"m",t:"Novas moradias",q:"O que a vida sedentária permitiu que as pessoas fizessem?",a:["Guardar alimentos e construir moradias duradouras","Desistir completamente da agricultura","Viver sem precisar de água","Carregar as casas nas costas"],c:0,e:"Morando fixo, dava para guardar grãos para o futuro e construir casas de verdade. A vida ficou mais organizada e segura."},
{n:"m",t:"Novas moradias",q:"Antes da agricultura, por que os grupos humanos costumavam ser pequenos?",a:["Porque as famílias viviam separadas por muros","Porque os deuses limitavam o tamanho dos grupos","Porque dependiam apenas do que a natureza oferecia","Porque era proibido andar em grupos grandes"],c:2,e:"Sem plantar, só dava para alimentar poucas pessoas com a caça e a coleta. Com a agricultura, a comida aumentou e os grupos cresceram."},
{n:"m",t:"Egito Antigo",q:"O que Heródoto quis dizer com a frase 'o Egito é uma dádiva do Nilo'?",a:["Que o Nilo pertencia aos gregos","Que o Egito só existia graças ao rio Nilo","Que o Egito deu o rio de presente aos vizinhos","Que o Nilo era um deus mais forte que o faraó"],c:1,e:"Sem o Nilo, o Egito seria só deserto. O rio dava água, comida e transporte — era como um presente que tornava a vida possível."},
{n:"m",t:"Egito Antigo",q:"O que os egípcios faziam logo depois que as águas da cheia baixavam?",a:["Abandonavam as margens do rio","Construíam muros para a água não voltar","Esperavam a próxima cheia sem plantar","Plantavam na terra adubada pelo húmus"],c:3,e:"A água baixava e deixava a terra escura e fértil. Era o momento perfeito para semear trigo, cevada e linho."},
{n:"m",t:"Egito Antigo",q:"Para que serviam os diques construídos pelos egípcios?",a:["Para servir de ponte para os barcos","Para marcar a divisa entre as cidades","Para decorar os jardins do faraó","Para segurar e controlar a água do rio"],c:3,e:"O dique é como uma barreira que segura a água. Assim os egípcios guardavam água da cheia e evitavam alagamentos fortes demais."},
{n:"m",t:"Egito Antigo",q:"Qual era a função dos canais de irrigação?",a:["Impedir a passagem de barcos inimigos","Levar a água do rio até plantações mais distantes","Criar caminhos para os pescadores andarem","Esconder tesouros embaixo da água"],c:1,e:"Os canais funcionavam como mangueiras gigantes: conduziam a água do Nilo até roças que ficavam longe da margem."},
{n:"m",t:"Egito Antigo",q:"O trigo e a cevada colhidos pelos egípcios serviam principalmente para fazer...",a:["tecidos e roupas","barcos e remos","pão e cerveja","tintas e pincéis"],c:2,e:"O trigo e a cevada eram a base da alimentação: viravam pães e também cerveja, bebida muito comum no Egito Antigo."},
{n:"m",t:"Egito Antigo",q:"Além de servir para escrever, para que mais o papiro era usado?",a:["Para fazer barcos, cestos e cordas","Para alimentar os bois de carga","Para construir as pirâmides","Para fabricar espadas e escudos"],c:0,e:"O papiro era um curinga: com seus talos os egípcios faziam barcos leves, cestos, esteiras e cordas, além das folhas de escrever."},
{n:"m",t:"Egito Antigo",q:"Como as pessoas e as mercadorias viajavam de uma cidade a outra no Egito?",a:["De trem, por trilhos no deserto","De carroça, por estradas de pedra na areia","De barco, navegando pelo rio Nilo","A pé, atravessando o deserto todos os dias"],c:2,e:"O Nilo era a grande avenida do Egito: os barcos subiam e desciam o rio levando gente, grãos e mercadorias."},
{n:"m",t:"Egito Antigo",q:"Por que os egípcios esperavam a cheia do Nilo com alegria, e não com medo?",a:["Porque a cheia trazia peixes dourados raros","Porque durante a cheia ninguém precisava trabalhar","Porque a cheia enchia as piscinas do palácio","Porque a cheia fertilizava a terra para o plantio"],c:3,e:"A cheia era sinal de fartura: depois dela, a terra ficava adubada e pronta para dar boas colheitas. Era festa, não susto!"},
{n:"m",t:"Egito Antigo",q:"O que poderia acontecer num ano em que o Nilo quase não enchesse?",a:["As colheitas seriam fracas e faltaria comida","O deserto viraria uma floresta","As pirâmides seriam desmontadas","O povo teria comida em dobro"],c:0,e:"Pouca cheia significava pouca terra adubada e pouca água. Resultado: colheita ruim e risco de fome no reino."},
{n:"m",t:"Egito Antigo",q:"O que é o húmus (ou limo) deixado pelas cheias?",a:["Um tipo de areia grossa do deserto","Uma camada de restos naturais que aduba a terra","Um sal que resseca as plantações","Uma pedra preciosa encontrada no rio"],c:1,e:"O húmus é formado por restos de plantas e outros materiais trazidos pela água. Ele funciona como adubo, deixando o solo cheio de nutrientes."},
{n:"m",t:"Egito Antigo",q:"Por que quase toda a população egípcia vivia perto do rio Nilo?",a:["Porque longe do rio havia apenas deserto","Porque o faraó proibia morar em outros lugares","Porque o mar ficava perto demais","Porque as montanhas escondiam o sol"],c:0,e:"A vida se concentrava na faixa verde do vale do Nilo. Para os lados, era areia a perder de vista — impossível plantar ou viver bem ali."},
{n:"m",t:"Egito Antigo",q:"Por que o deserto do Saara também ajudava a proteger o Egito?",a:["Porque escondia o Egito debaixo da areia","Porque dificultava a chegada de exércitos invasores","Porque os inimigos tinham medo de escorpiões","Porque o deserto pertencia aos deuses"],c:1,e:"Atravessar quilômetros de areia quente, sem água, era quase impossível para um exército. O deserto era uma muralha natural do Egito."},
{n:"m",t:"Egito Antigo",q:"Por que o linho era uma plantação importante para os egípcios?",a:["Porque era o alimento preferido do faraó","Porque servia para construir casas","Porque espantava os insetos das margens","Porque dele se faziam fios e tecidos"],c:3,e:"O linho virava fio, e o fio virava tecido leve e fresquinho, ideal para o calor. Até as faixas de múmia eram de linho!"},
{n:"m",t:"Sociedade egípcia",q:"Por que o faraó tinha poder total sobre o Egito?",a:["Porque era o homem mais velho do reino","Porque vencia corridas de barcos no Nilo","Porque era considerado um deus vivo na Terra","Porque era eleito pelo voto dos camponeses"],c:2,e:"Como o povo acreditava que o faraó era um deus, desobedecê-lo seria desobedecer aos céus. Isso dava a ele um poder enorme."},
{n:"m",t:"Sociedade egípcia",q:"Por que os escribas eram tão valorizados no Egito?",a:["Porque eram os únicos que sabiam nadar","Porque guardavam as chaves das pirâmides","Porque eram os donos das terras férteis","Porque pouquíssimas pessoas sabiam ler e escrever"],c:3,e:"Num reino onde quase ninguém escrevia, quem dominava os símbolos era raro e necessário — como um especialista superprocurado."},
{n:"m",t:"Sociedade egípcia",q:"Quem anotava os impostos e o tamanho das colheitas para o governo?",a:["Os escribas","Os soldados","Os artesãos","Os escravizados"],c:0,e:"Os escribas eram os anotadores oficiais do Egito: registravam impostos, colheitas e tudo o que o governo precisava controlar."},
{n:"m",t:"Sociedade egípcia",q:"Por que os sacerdotes tinham tanto prestígio na sociedade egípcia?",a:["Porque eram os melhores guerreiros do reino","Porque fabricavam as joias do faraó","Porque cuidavam da ligação entre o povo e os deuses","Porque eram os únicos que pescavam no Nilo"],c:2,e:"Numa terra em que a religião mandava em tudo, quem falava com os deuses tinha grande poder: esse era o papel dos sacerdotes."},
{n:"m",t:"Sociedade egípcia",q:"Na pirâmide social, quem estava mais perto do topo: os sacerdotes ou os camponeses?",a:["Os camponeses, porque alimentavam o reino","Os sacerdotes, logo abaixo do faraó","Os dois ficavam juntos no meio","Nenhum deles aparecia na pirâmide"],c:1,e:"Os sacerdotes ficavam bem no alto, perto do faraó. Os camponeses, apesar de importantes, ficavam perto da base, com pouco poder."},
{n:"m",t:"Sociedade egípcia",q:"Quando os campos ficavam alagados pelas cheias, o que muitos camponeses faziam?",a:["Tiravam férias nas margens do rio","Trabalhavam nas grandes construções do faraó","Viravam sacerdotes por alguns meses","Partiam para morar no deserto"],c:1,e:"Com a roça debaixo d'água, os braços dos camponeses eram usados nas obras do reino, como templos e pirâmides."},
{n:"m",t:"Sociedade egípcia",q:"Qual é a diferença entre o trabalho do artesão e o do camponês?",a:["O artesão reza nos templos; o camponês escreve","O artesão governa; o camponês comanda o exército","O artesão fabrica objetos; o camponês cultiva a terra","O artesão pesca; o camponês constrói barcos"],c:2,e:"Cada um tinha seu ofício: o camponês fazia a comida nascer da terra, e o artesão transformava materiais em vasos, joias e móveis."},
{n:"m",t:"Sociedade egípcia",q:"Um menino egípcio que estudasse anos para aprender os hieróglifos queria se tornar...",a:["escriba","camponês","soldado","pescador"],c:0,e:"Ser escriba exigia anos de estudo puxado, copiando símbolos sem parar. Em troca, era uma das melhores posições da sociedade."},
{n:"m",t:"Sociedade egípcia",q:"Por que os camponeses ficavam perto da base da pirâmide social?",a:["Porque eram os mais ricos do reino","Porque moravam dentro do palácio","Porque se recusavam a pagar impostos","Porque trabalhavam muito, mas tinham pouco poder e riqueza"],c:3,e:"Os camponeses sustentavam o Egito com seu trabalho, mas quase tudo o que produziam ia para impostos. Muito suor, pouco poder."},
{n:"m",t:"Sociedade egípcia",q:"Qual grupo vivia sem liberdade, obrigado a trabalhar para os outros?",a:["Os escravizados","Os comerciantes","Os escribas","Os sacerdotes"],c:0,e:"Na base da pirâmide, as pessoas escravizadas não escolhiam seu destino: eram forçadas a trabalhar e não tinham os direitos dos demais."},
{n:"m",t:"Sociedade egípcia",q:"O que os comerciantes egípcios faziam com produtos como grãos, tecidos e joias?",a:["Jogavam no rio como oferenda","Guardavam tudo nas pirâmides","Vendiam e trocavam dentro e fora do Egito","Queimavam nos festivais do faraó"],c:2,e:"Os comerciantes movimentavam o Egito: trocavam e vendiam mercadorias nos mercados e até com povos de outras terras."},
{n:"m",t:"Sociedade egípcia",q:"Na sociedade egípcia, quem dava ordens que valiam para todos os grupos?",a:["Os artesãos mais velhos","Os camponeses reunidos","Os comerciantes ricos","O faraó"],c:3,e:"Do topo da pirâmide, a palavra do faraó era lei para sacerdotes, soldados, camponeses — todo mundo, sem exceção."},
{n:"m",t:"Deuses do Nilo",q:"Por que os egípcios agradeciam aos deuses quando o Nilo enchia?",a:["Porque os sacerdotes cobravam multas de quem não agradecia","Porque era a única festa que existia no ano","Porque o faraó pagava por cada agradecimento","Porque acreditavam que os deuses controlavam a natureza"],c:3,e:"Para os egípcios, nada na natureza acontecia por acaso: a cheia era um presente dos deuses, e presentes merecem agradecimento."},
{n:"m",t:"Deuses do Nilo",q:"Se um camponês egípcio quisesse pedir uma boa colheita, o que ele provavelmente faria?",a:["Escreveria uma carta ao rei da Grécia","Levaria oferendas a um templo","Jogaria as sementes no deserto","Pediria a um escriba para plantar por ele"],c:1,e:"Pedidos aos deuses eram feitos com oferendas nos templos: alimentos, flores e presentes para agradar e conseguir proteção."},
{n:"m",t:"Deuses do Nilo",q:"Em uma pintura de funeral egípcio, qual deus com cabeça de chacal costuma aparecer?",a:["Anúbis","Rá","Hathor","Hórus"],c:0,e:"Anúbis era o deus da mumificação, por isso aparece nas cenas de funeral, cuidando da passagem dos mortos para a outra vida."},
{n:"m",t:"Deuses do Nilo",q:"Qual deus os egípcios associavam ao Sol que atravessa o céu todos os dias?",a:["Osíris","Anúbis","Rá","Ísis"],c:2,e:"Rá era o deus-sol. Os egípcios imaginavam que ele viajava pelo céu de barco, iluminando o mundo do amanhecer ao pôr do sol."},
{n:"m",t:"Deuses do Nilo",q:"Na crença egípcia, quem reinava sobre o mundo dos mortos?",a:["Osíris","Hathor","Rá","O faraó Quéops"],c:0,e:"Osíris era o rei do mundo dos mortos. Os egípcios acreditavam que ele recebia as pessoas que morriam."},
{n:"m",t:"Deuses do Nilo",q:"Qual é a diferença entre politeísmo e monoteísmo?",a:["Politeísmo é não ter religião; monoteísmo é ter várias","Politeísmo é crer em um deus; monoteísmo, em vários","Os dois significam exatamente a mesma coisa","Politeísmo é crer em vários deuses; monoteísmo, em um só"],c:3,e:"'Poli' = muitos, 'mono' = um. Os egípcios eram politeístas; religiões com um único deus são monoteístas."},
{n:"m",t:"Deuses do Nilo",q:"Hórus, deus do céu, era representado com cabeça de qual animal?",a:["Crocodilo","Gato","Falcão","Touro"],c:2,e:"Hórus tem cabeça de falcão, ave que voa alto e enxerga longe — perfeita para um deus ligado ao céu."},
{n:"m",t:"Deuses do Nilo",q:"Por que existiam tantos templos espalhados pelo Egito?",a:["Porque sobrava pedra depois das pirâmides","Porque a religião fazia parte de toda a vida dos egípcios","Porque os templos serviam de mercado","Porque cada família era obrigada a construir um"],c:1,e:"A religião acompanhava o egípcio do nascimento à morte. Com deuses para tudo, havia templos por toda parte para honrá-los."},
{n:"m",t:"Deuses do Nilo",q:"Ísis, esposa de Osíris e mãe de Hórus, era vista pelos egípcios como...",a:["uma rainha humana comum","uma inimiga dos outros deuses","uma deusa protetora","uma cidade sagrada"],c:2,e:"Ísis era amada como grande mãe e protetora. Sua família divina — Osíris e Hórus — está entre as mais famosas do Egito."},
{n:"m",t:"Deuses do Nilo",q:"O que os egípcios queriam mostrar ao dar aos deuses cabeças de animais?",a:["As qualidades de cada animal, como força ou visão aguçada","Que os animais mandavam nos humanos","Que não sabiam desenhar rostos humanos","Que os deuses tinham medo das pessoas"],c:0,e:"Cada animal emprestava seu poder ao deus: o falcão enxerga longe, o chacal ronda o deserto. Era um jeito de mostrar as qualidades divinas."},
{n:"m",t:"Deuses do Nilo",q:"Quem realizava as cerimônias dentro dos templos egípcios?",a:["Os comerciantes","Os sacerdotes","Os soldados","Os camponeses"],c:1,e:"Os templos eram como a casa dos deuses, e os sacerdotes eram seus cuidadores: faziam rituais, oferendas e orações."},
{n:"m",t:"Deuses do Nilo",q:"Por que desobedecer ao faraó era considerado algo tão grave?",a:["Porque o exército invadia a casa da pessoa","Porque a pessoa perdia o direito de pescar","Porque os comerciantes aumentavam os preços","Porque, para o povo, era como desobedecer a um deus"],c:3,e:"Como o faraó era visto como deus vivo, suas ordens tinham força sagrada. Contrariá-lo era desafiar a própria religião."},
{n:"m",t:"Escrita hieroglífica",q:"Por que a Pedra de Roseta foi tão importante para os estudiosos?",a:["Porque era feita de ouro puro","Porque trazia o mesmo texto em escritas diferentes","Porque mostrava o mapa das pirâmides","Porque foi escrita pelo próprio faraó Quéops"],c:1,e:"Com o mesmo texto em hieróglifos e em grego, deu para comparar as escritas — como usar um gabarito para corrigir uma prova."},
{n:"m",t:"Escrita hieroglífica",q:"Por que os hieróglifos ficaram muitos séculos sem ser compreendidos?",a:["Porque eram escritos com tinta invisível","Porque os templos ficavam trancados","Porque ninguém mais sabia ler aqueles símbolos","Porque era proibido olhar para eles"],c:2,e:"Com o fim do Egito Antigo, a leitura dos símbolos foi esquecida. Os desenhos continuavam lá, mas viraram um mistério sem tradução."},
{n:"m",t:"Escrita hieroglífica",q:"O que os escribas registravam nos papiros?",a:["Apenas os nomes dos faraós","Somente mapas do deserto","Apenas cantigas dos camponeses","Impostos, colheitas e textos importantes do reino"],c:3,e:"Os escribas anotavam os números e documentos do reino: quanto se colheu, quanto se pagou de imposto, além de textos religiosos."},
{n:"m",t:"Escrita hieroglífica",q:"Onde um arqueólogo tem mais chance de encontrar hieróglifos gravados?",a:["Nas paredes de templos e tumbas","No fundo do mar Mediterrâneo","Nas árvores das florestas africanas","Nas geleiras das montanhas"],c:0,e:"Como era uma escrita sagrada, os hieróglifos decoravam templos e tumbas — lugares que resistiram ao tempo e podem ser escavados hoje."},
{n:"m",t:"Escrita hieroglífica",q:"Como as folhas de papiro eram fabricadas?",a:["Derretendo areia do deserto","Costurando peles de cabra","Misturando barro com água do Nilo","Com tiras da planta prensadas umas sobre as outras"],c:3,e:"Os egípcios cortavam o talo do papiro em tiras, cruzavam e prensavam tudo até virar uma folha lisa. Pronto: o 'papel' egípcio!"},
{n:"m",t:"Escrita hieroglífica",q:"Qual escrita da Pedra de Roseta os estudiosos já conheciam, o que ajudou na decifração?",a:["O grego","O chinês","O japonês","O russo"],c:0,e:"A pedra tinha o texto também em grego, língua que os estudiosos liam. Comparando o grego com os hieróglifos, Champollion achou a chave."},
{n:"m",t:"Escrita hieroglífica",q:"Por que saber escrever garantia empregos importantes no Egito?",a:["Porque os livros eram vendidos por preços altos","Porque o governo precisava registrar impostos e colheitas","Porque escrever era um esporte popular","Porque só quem escrevia podia pescar no Nilo"],c:1,e:"Um reino grande precisa de registros e contas em dia. Quem sabia escrever era essencial para o governo funcionar — e era recompensado."},
{n:"m",t:"Escrita hieroglífica",q:"Nos hieróglifos, os desenhos podiam representar...",a:["apenas números","somente nomes de deuses","sons e ideias","apenas cores"],c:2,e:"Um desenho podia valer por um som ou por uma ideia inteira. Por isso os hieróglifos eram tão numerosos e difíceis de aprender."},
{n:"m",t:"Escrita hieroglífica",q:"Por que aprender a ser escriba demorava anos?",a:["Porque as aulas só aconteciam uma vez por ano","Porque era preciso memorizar centenas de símbolos","Porque os professores viviam viajando","Porque só se estudava de madrugada"],c:1,e:"Não era um alfabeto de poucas letras: eram centenas de sinais! Os aprendizes copiavam e treinavam por anos até dominar tudo."},
{n:"m",t:"Escrita hieroglífica",q:"Sem a decifração dos hieróglifos, o que seria mais difícil para nós hoje?",a:["Visitar o Egito de avião","Construir museus modernos","Fotografar as pirâmides de longe","Conhecer a história registrada pelos próprios egípcios"],c:3,e:"Os textos egípcios contam a história na voz deles mesmos. Sem entender os símbolos, teríamos apenas objetos mudos, sem as explicações."},
{n:"m",t:"Escrita hieroglífica",q:"Por que a escrita hieroglífica era chamada de sagrada?",a:["Porque só o faraó podia lê-la","Porque era escrita com tinta de ouro","Porque era usada em textos religiosos, templos e tumbas","Porque caía do céu pronta nos papiros"],c:2,e:"Os egípcios ligavam essa escrita aos deuses: ela registrava orações e textos religiosos nos lugares mais sagrados do reino."},
{n:"m",t:"Mumificação",q:"Na crença egípcia, por que era tão importante conservar o corpo do morto?",a:["Para que a alma pudesse reconhecê-lo e voltar a ele","Para o corpo ser vendido no mercado","Para os soldados guardarem como troféu","Para o corpo virar estátua do templo"],c:0,e:"Os egípcios acreditavam que a alma continuava viva e precisava do corpo como casa. Corpo conservado, alma com endereço certo!"},
{n:"m",t:"Mumificação",q:"O que era retirado do corpo logo no início da mumificação?",a:["Os órgãos internos","Os cabelos e as unhas","Os ossos das pernas","Os dentes da frente"],c:0,e:"O processo começava com a retirada dos órgãos internos, que iam para os vasos canópicos. Isso evitava que o corpo apodrecesse."},
{n:"m",t:"Mumificação",q:"Qual era a função do natrão no processo de mumificação?",a:["Perfumar a tumba do faraó","Colar as faixas de linho","Retirar a umidade e secar o corpo","Pintar o sarcófago de dourado"],c:2,e:"O natrão é um sal que bebe toda a água do corpo. Sem umidade, o corpo não apodrece — o mesmo truque do sal na carne-seca."},
{n:"m",t:"Mumificação",q:"Por que os egípcios enterravam comida, joias e objetos junto com os mortos?",a:["Porque não havia espaço nas casas","Porque era proibido herdar objetos","Porque os objetos estragavam fora das tumbas","Porque acreditavam que o morto usaria tudo na outra vida"],c:3,e:"A morte era vista como uma viagem. E quem viaja leva bagagem: comida, roupas e joias para usar na vida após a morte."},
{n:"m",t:"Mumificação",q:"Qual é a ordem correta destas etapas da mumificação?",a:["Enfaixar o corpo, retirar os órgãos, secar com natrão","Retirar os órgãos, secar com natrão, enfaixar o corpo","Secar com natrão, enfaixar o corpo, retirar os órgãos","Enfaixar o corpo, secar com natrão, retirar os órgãos"],c:1,e:"Primeiro tiravam os órgãos, depois secavam o corpo com natrão e, por último, enrolavam nas faixas de linho. Ordem certinha para conservar bem!"},
{n:"m",t:"Mumificação",q:"Por que as pirâmides eram construídas tão grandes e resistentes?",a:["Para servir de moradia aos sacerdotes","Para os soldados vigiarem o deserto de cima","Para proteger o corpo e os tesouros do faraó para sempre","Para guardar a colheita de trigo do ano"],c:2,e:"A pirâmide era o túmulo eterno do faraó. Quanto mais forte e grandiosa, mais protegido ficava tudo o que havia dentro dela."},
{n:"m",t:"Mumificação",q:"Quem tinha direito a ser enterrado nas grandes pirâmides?",a:["Todos os egípcios, sem exceção","Os faraós","Apenas os escribas mais estudiosos","Os comerciantes mais ricos"],c:1,e:"Pirâmide era coisa de faraó! As outras pessoas eram enterradas de formas mais simples, conforme suas posses."},
{n:"m",t:"Mumificação",q:"Qual é a diferença entre o sarcófago e os vasos canópicos?",a:["O sarcófago guarda o corpo; os vasos guardam os órgãos","O sarcófago guarda joias; os vasos guardam perfume","O sarcófago fica no templo; os vasos, no palácio","O sarcófago é de papiro; os vasos são de linho"],c:0,e:"Cada um tem seu papel: a múmia descansa no sarcófago, e os órgãos retirados ficam pertinho, nos vasos canópicos."},
{n:"m",t:"Mumificação",q:"Por que nem todos os egípcios eram mumificados com todo o luxo?",a:["Porque faltava linho no Egito","Porque a lei permitia mumificar apenas uma pessoa por ano","Porque o povo não acreditava na vida após a morte","Porque a mumificação completa era muito cara"],c:3,e:"Mumificar bem custava caro: natrão, linho, sarcófago, especialistas... Famílias simples faziam versões mais baratas do ritual."},
{n:"m",t:"Mumificação",q:"A Esfinge de Gizé, com corpo de leão e cabeça humana, parece ter a função de...",a:["guardar e proteger as pirâmides","marcar onde o Nilo enchia","servir de moradia para os sacerdotes","esconder um poço de água"],c:0,e:"Imponente diante das pirâmides, a Esfinge lembra um guardião gigante, unindo a força do leão à inteligência humana."},
{n:"m",t:"Mumificação",q:"As três grandes pirâmides de Gizé foram construídas para quais faraós?",a:["Heródoto, Champollion e Roseta","Quéops, Quéfren e Miquerinos","Rá, Osíris e Hórus","Anúbis, Ísis e Hathor"],c:1,e:"Cada pirâmide de Gizé é o túmulo de um faraó: Quéops, Quéfren e Miquerinos. Os outros nomes são de deuses e estudiosos, não de faraós dali."},
{n:"m",t:"Mumificação",q:"Por que a mumificação completa demorava muitos dias?",a:["Porque os sacerdotes trabalhavam apenas uma hora por dia","Porque era preciso esperar a cheia do rio","Porque o sarcófago vinha de barco da Grécia","Porque secar e preparar o corpo exigia muito cuidado"],c:3,e:"Cada etapa levava tempo: retirar os órgãos, deixar o natrão secar o corpo por semanas e enfaixar com capricho. Trabalho de especialistas."},
{n:"d",t:"Novas moradias",q:"Por que os grupos nômades não construíam moradias duradouras?",a:["Porque não existiam pedras na natureza","Porque logo partiriam para outro lugar","Porque dormir ao relento fazia parte da religião","Porque as leis dos reis proibiam construções"],c:1,e:"Para quem se muda o tempo todo, não vale a pena gastar meses construindo uma casa firme. Abrigos simples eram mais práticos. 🏕️"},
{n:"d",t:"Novas moradias",q:"Qual sequência mostra a ordem correta dos acontecimentos?",a:["Encontrar terra fértil, começar a plantar, fixar moradia","Fixar moradia, encontrar terra fértil, começar a plantar","Começar a plantar, abandonar a região, virar nômade","Construir cidades, descobrir a agricultura, virar nômade"],c:0,e:"Primeiro o grupo acha um bom lugar, depois começa a plantar e, como a plantação exige espera, acaba se fixando ali. Um passo puxa o outro."},
{n:"d",t:"Novas moradias",q:"Um grupo se fixou perto de um rio, mas o rio secou de vez. O que provavelmente aconteceu?",a:["O grupo fez o rio voltar com festas","O grupo passou a beber água do mar","O grupo precisou migrar em busca de outro lugar com água","O grupo continuou vivendo normalmente sem água"],c:2,e:"Sem água não há plantação, criação nem vida. Mesmo grupos sedentários precisavam partir se a natureza mudasse de vez."},
{n:"d",t:"Novas moradias",q:"Qual vantagem o grupo sedentário tinha sobre o nômade?",a:["Nunca passava por nenhuma dificuldade","Não precisava mais trabalhar para comer","Podia carregar a aldeia inteira nas costas","Podia guardar alimentos e planejar as próximas colheitas"],c:3,e:"Morando fixo, dava para encher os celeiros e se preparar para o futuro. Já o nômade só podia carregar o que coubesse na viagem."},
{n:"d",t:"Novas moradias",q:"A sedentarização aconteceu somente no Egito?",a:["Sim; só os egípcios pararam de migrar","Sim; o resto do mundo continua nômade até hoje","Não; ela aconteceu apenas nos desertos","Não; ela ocorreu em várias regiões com rios e terras férteis"],c:3,e:"Outros povos também se fixaram perto de grandes rios em diferentes partes do mundo. O Egito é um exemplo famoso, mas não o único."},
{n:"d",t:"Novas moradias",q:"Por que a sedentarização favoreceu o surgimento de vilas e cidades?",a:["Porque os nômades desenhavam mapas de cidades","Porque as casas eram levadas de um lado para outro","Porque muitas pessoas passaram a viver juntas no mesmo lugar por gerações","Porque o deserto encolheu de repente"],c:2,e:"Gente parada no mesmo lugar, colheita rendendo, famílias crescendo... As aldeias foram aumentando até virarem vilas e cidades."},
{n:"d",t:"Novas moradias",q:"Qual destas atividades é típica de um grupo nômade?",a:["Construir diques e canais de irrigação","Seguir as manadas de animais para caçar","Guardar grãos em celeiros de barro","Erguer templos de pedra para os deuses"],c:1,e:"O nômade vai atrás do alimento que se move. Já diques, celeiros e templos são obras de quem resolveu ficar."},
{n:"d",t:"Novas moradias",q:"O que a agricultura exigia que a caça e a coleta não exigiam?",a:["Permanecer meses no mesmo lugar cuidando da plantação","Conhecer os caminhos dos animais","Saber quais frutos eram venenosos","Andar grandes distâncias todos os dias"],c:0,e:"Plantar é um compromisso com o lugar: preparar a terra, semear, regar e esperar. Quem caça e coleta pode partir a qualquer momento."},
{n:"d",t:"Novas moradias",q:"Por que construir canais de irrigação exigia que as pessoas se organizassem em grupo?",a:["Porque era um trabalho grande demais para uma pessoa ou família sozinha","Porque cavar sozinho era considerado azar","Porque as ferramentas só funcionavam em dupla","Porque os canais eram cavados apenas à noite"],c:0,e:"Abrir canais quilométricos exigia muitos braços, combinação e liderança. As grandes obras coletivas ajudaram a organizar a sociedade."},
{n:"d",t:"Novas moradias",q:"Por que os grupos precisavam de água E terra fértil, e não apenas de um dos dois?",a:["Porque a água servia só para os animais beberem","Porque a terra fértil substituía a água na plantação","Porque era um costume religioso escolher os dois","Porque sem água nada cresce e, sem terra boa, a semente não vinga"],c:3,e:"É como um bolo que precisa de massa E forno: faltando um, não sai bolo. Água sem terra boa, ou terra boa sem água, não davam colheita."},
{n:"d",t:"Egito Antigo",q:"Ao dizer que o Egito era uma 'dádiva do Nilo', Heródoto quis destacar que...",a:["o Nilo foi cavado pelos operários egípcios","o Egito presenteou a Grécia com um rio","a própria existência do Egito dependia do rio","o Nilo era o único rio do mundo"],c:2,e:"Heródoto percebeu que tudo no Egito — comida, transporte, moradia — vinha do rio. Tirando o Nilo, restaria só deserto."},
{n:"d",t:"Egito Antigo",q:"Sobre as cheias do Nilo, qual ideia está correta?",a:["Eram evitadas com muros altos em todo o rio","Eram esperadas com alegria, pois adubavam a terra","Destruíam o Egito e causavam fome todos os anos","Aconteciam de surpresa, sem época certa"],c:1,e:"A cheia era bem-vinda! Ela vinha em época certa do ano e deixava o húmus que garantia boas colheitas. Era o contrário de um desastre."},
{n:"d",t:"Egito Antigo",q:"No ciclo do ano egípcio, o que vinha logo depois da cheia?",a:["A colheita imediata dos frutos","Outra cheia ainda maior","O plantio na terra fertilizada","A festa da construção de pirâmides"],c:2,e:"A ordem era: cheia, plantio e, meses depois, colheita. Primeiro a água aduba a terra; só então se planta — colher é o passo final."},
{n:"d",t:"Egito Antigo",q:"O deserto do Saara, além de limitar as áreas de plantio, tinha qual efeito 'positivo' para o Egito?",a:["Fornecia areia para fazer pão","Dificultava invasões de povos inimigos","Refrescava as noites dos camponeses","Produzia chuva para as plantações"],c:1,e:"Atravessar o deserto era um desafio mortal para exércitos: sem água e sob calor extremo. O Saara acabava servindo de escudo natural."},
{n:"d",t:"Egito Antigo",q:"Como os canais permitiam plantar longe das margens do rio?",a:["Empurrando a terra fértil para dentro do rio","Transformando areia do deserto em água doce","Fazendo o rio mudar de lugar todos os meses","Conduzindo a água do Nilo até terras mais distantes"],c:3,e:"O canal leva a água aonde ela não chegaria sozinha, como uma mangueira comprida. Assim, mais terras podiam ser cultivadas."},
{n:"d",t:"Egito Antigo",q:"Qual destas afirmações sobre o rio Nilo está ERRADA?",a:["Ele enchia duas vezes por mês, sem época certa","Ele servia de caminho para os barcos","Ele fornecia peixes para a alimentação","Suas cheias deixavam húmus fértil na terra"],c:0,e:"Quase tudo é verdade sobre o Nilo — menos a frequência: a cheia era uma vez por ano, em época conhecida, e não duas vezes por mês."},
{n:"d",t:"Egito Antigo",q:"Se as cheias falhassem por vários anos seguidos, o que aconteceria com o Egito?",a:["Haveria fome e uma grande crise no reino","Nada mudaria na vida dos camponeses","As colheitas dobrariam de tamanho","O deserto viraria um jardim verde"],c:0,e:"Sem cheia, sem húmus e sem água para irrigar: as colheitas fracassariam. Anos assim seguidos significavam fome e crise séria."},
{n:"d",t:"Egito Antigo",q:"Por que o húmus é diferente da areia do deserto?",a:["Porque é mais claro e mais quente que a areia","Porque é rico em nutrientes que alimentam as plantas","Porque é feito de pedras trituradas pelos ventos","Porque brilha à noite nas margens do rio"],c:1,e:"A areia é pobre: quase nenhum nutriente. Já o húmus é um prato cheio para as plantas, com restos naturais que viram adubo."},
{n:"d",t:"Egito Antigo",q:"Para guardar água da cheia e usá-la nos meses secos, os egípcios contavam com...",a:["barcos que traziam água do mar","chuvas fortes do inverno","diques e reservatórios que seguravam a água","poços cavados no meio do deserto"],c:2,e:"Os diques represavam a água da cheia para ela não ir embora de vez. Assim havia água para irrigar mesmo na estação seca."},
{n:"d",t:"Egito Antigo",q:"Comparando com os dias de hoje, o rio Nilo funcionava para os egípcios como...",a:["um estádio para competições","uma muralha que ninguém cruzava","um museu de coisas antigas","uma grande estrada por onde circulavam pessoas e mercadorias"],c:3,e:"Quase tudo viajava de barco pelo rio: grãos, pedras, pessoas. O Nilo era a rodovia que ligava as cidades do Egito."},
{n:"d",t:"Egito Antigo",q:"O linho e o papiro eram plantações que não serviam de comida. O que os egípcios produziam com elas?",a:["Pão com o linho e cerveja com o papiro","Tecidos com o linho e folhas de escrever com o papiro","Remédios com o linho e joias com o papiro","Barcos com o linho e espadas com o papiro"],c:1,e:"Nem tudo que se planta vai para o prato: o linho virava tecido e o papiro virava 'papel', barcos e cestos. Plantações para vestir e escrever!"},
{n:"d",t:"Egito Antigo",q:"Por que podemos dizer que a agricultura egípcia seguia um 'calendário natural'?",a:["Porque os egípcios plantavam em qualquer época, sem regras","Porque as sementes só germinavam nas festas religiosas","Porque o plantio seguia o ritmo anual das cheias do rio","Porque o faraó sorteava o dia do plantio"],c:2,e:"A natureza dava o sinal: cheia chegou, cheia baixou, hora de plantar. O ano egípcio era organizado em volta do comportamento do rio."},
{n:"d",t:"Egito Antigo",q:"O Egito fica no nordeste da África. Qual paisagem domina as terras FORA do vale do Nilo?",a:["Deserto seco e arenoso","Floresta tropical úmida","Campos de gelo e neve","Pântanos cobertos de vitórias-régias"],c:0,e:"Saindo da faixa verde do rio, o que se vê é o Saara: areia e pedra a perder de vista. Por isso o vale do Nilo era tão precioso."},
{n:"d",t:"Sociedade egípcia",q:"Um colega disse: 'Os escribas ficavam na base da pirâmide social'. Por que ele está enganado?",a:["Porque os escribas nem apareciam na sociedade","Porque a base era ocupada pelos sacerdotes","Porque não existiam escribas no Egito","Porque os escribas tinham posição elevada, perto do topo"],c:3,e:"Saber escrever era raríssimo e valioso, então os escribas ficavam no alto da pirâmide, com prestígio — nada de base!"},
{n:"d",t:"Sociedade egípcia",q:"Por que o desenho de uma pirâmide representa bem a sociedade egípcia?",a:["Porque os egípcios moravam dentro das pirâmides","Porque todos na sociedade eram construtores","Porque o Egito tinha exatamente três grupos sociais","Porque poucos tinham muito poder no topo e muitos tinham pouco poder na base"],c:3,e:"No topo estreito cabem poucos (faraó, sacerdotes); na base larga, a multidão (camponeses, escravizados). O formato conta a história do poder."},
{n:"d",t:"Sociedade egípcia",q:"Como a religião fortalecia o poder do faraó?",a:["Fazendo o povo ver as ordens dele como ordens divinas","Ensinando o povo a escolher governantes pelo voto","Impedindo o faraó de tomar decisões","Obrigando o faraó a trabalhar nos templos"],c:0,e:"Se o chefe é visto como deus, quem vai discutir? A religião fazia o poder do faraó parecer sagrado e inquestionável."},
{n:"d",t:"Sociedade egípcia",q:"Um comerciante precisava enviar uma mensagem escrita ao palácio. A quem ele recorreria?",a:["A um camponês","A um escriba","A um soldado","A um escravizado"],c:1,e:"Como quase ninguém sabia escrever, era o escriba quem colocava no papiro as palavras de quem precisava se comunicar por escrito."},
{n:"d",t:"Sociedade egípcia",q:"Qual grupo social NÃO vivia do próprio trabalho livre?",a:["Os artesãos","Os comerciantes","Os escravizados","Os camponeses"],c:2,e:"Artesãos, comerciantes e camponeses trabalhavam duro, mas eram livres. Já os escravizados eram forçados a trabalhar para os outros, sem escolha."},
{n:"d",t:"Sociedade egípcia",q:"Por que era tão difícil alguém mudar de grupo social no Egito Antigo?",a:["Porque havia provas anuais para trocar de grupo","Porque ninguém queria melhorar de vida","Porque a posição social costumava passar de pais para filhos","Porque era proibido aprender qualquer ofício"],c:2,e:"Filho de camponês crescia camponês; filho de artesão, artesão. A escada social era travada — subir era raro como ganhar um prêmio."},
{n:"d",t:"Sociedade egípcia",q:"Qual é a diferença entre as funções dos sacerdotes e as dos escribas?",a:["Sacerdotes plantavam; escribas colhiam","Sacerdotes governavam; escribas eram faraós","Sacerdotes lutavam; escribas pescavam","Sacerdotes cuidavam do culto aos deuses; escribas, dos registros escritos"],c:3,e:"Cada especialista no seu posto: o sacerdote comandava rituais e templos; o escriba anotava impostos, colheitas e documentos."},
{n:"d",t:"Sociedade egípcia",q:"Na pirâmide social egípcia, qual sequência vai do MAIOR para o MENOR poder?",a:["Faraó, sacerdotes, camponeses, escravizados","Escravizados, camponeses, sacerdotes, faraó","Camponeses, faraó, escravizados, sacerdotes","Sacerdotes, escravizados, faraó, camponeses"],c:0,e:"Do topo à base: o faraó manda em tudo, os sacerdotes vêm logo abaixo, os camponeses ficam perto da base e os escravizados por último."},
{n:"d",t:"Sociedade egípcia",q:"De onde vinham os recursos que sustentavam o faraó e as grandes obras?",a:["De empréstimos feitos pelos gregos","Dos impostos e do trabalho do povo, principalmente dos camponeses","Da venda das pirâmides antigas","De minas de ouro na Europa"],c:1,e:"Quem sustentava o luxo do topo era a base: os camponeses entregavam parte das colheitas como imposto e ainda trabalhavam nas obras."},
{n:"d",t:"Sociedade egípcia",q:"Quando o faraó morria, quem normalmente assumia o trono?",a:["Alguém da própria família, como o filho","O camponês mais trabalhador do ano","Um comerciante sorteado no mercado","O soldado mais forte do exército"],c:0,e:"O poder era hereditário: passava dentro da família, de pai para filho, como uma herança. O povo não escolhia o governante."},
{n:"d",t:"Sociedade egípcia",q:"Um artesão que fazia joias para o palácio pertencia a qual parte da pirâmide social?",a:["Ao topo, junto com o faraó","À parte do meio, entre o topo e a base","À base, junto com os escravizados","A nenhuma: artesãos não entravam na pirâmide"],c:1,e:"Mesmo fazendo joias para gente importante, o artesão seguia no meio da pirâmide: acima de camponeses e escravizados, abaixo dos poderosos."},
{n:"d",t:"Sociedade egípcia",q:"Por que os soldados eram importantes para o poder do faraó?",a:["Porque plantavam nas terras do palácio","Porque escreviam as leis do Egito","Porque defendiam o reino e garantiam a ordem","Porque cuidavam das cerimônias dos templos"],c:2,e:"Com o exército, o faraó protegia o Egito de invasores e mantinha todos obedecendo às regras. Força a serviço do trono."},
{n:"d",t:"Deuses do Nilo",q:"Dizer que os egípcios eram politeístas significa que eles:",a:["não acreditavam em nenhum deus","acreditavam em vários deuses ao mesmo tempo","acreditavam em um único deus","adoravam apenas o faraó"],c:1,e:"'Poli' quer dizer muitos e 'teísmo' quer dizer deus: politeísmo é acreditar em vários deuses. O contrário seria monoteísmo."},
{n:"d",t:"Deuses do Nilo",q:"Muitos deuses egípcios eram representados com corpo humano e cabeça de animal. Isso acontecia porque:",a:["os egípcios não sabiam desenhar pessoas","cada animal representava qualidades que se atribuíam àquele deus","eles queriam esconder o rosto dos deuses","os animais eram proibidos no Egito"],c:1,e:"O animal funcionava como símbolo: o falcão de Hórus lembra visão e altura; o chacal de Anúbis lembra os cemitérios do deserto."},
{n:"d",t:"Deuses do Nilo",q:"Rá era considerado um dos deuses mais importantes do Egito porque representava:",a:["o Sol, fonte de luz, calor e vida","o vento do deserto","a escrita dos escribas","a guerra contra outros povos"],c:0,e:"Rá era o deus Sol. Como o Sol garantia luz e colheitas, ele estava ligado à própria vida do Egito. ☀️"},
{n:"d",t:"Deuses do Nilo",q:"Anúbis, representado com cabeça de chacal, estava ligado principalmente:",a:["à colheita do trigo","à mumificação e à proteção dos mortos","à construção de barcos","ao ensino da escrita"],c:1,e:"Anúbis acompanhava o processo de mumificação e guiava o morto. Chacais rondavam os cemitérios, daí a imagem."},
{n:"d",t:"Deuses do Nilo",q:"Osíris era associado ao mundo dos mortos e também ao renascimento da natureza. Essa ligação fazia sentido para os egípcios porque:",a:["o Nilo secava e não voltava mais","as cheias do Nilo faziam a terra 'morrer' e renascer a cada ano","não havia plantações no Egito","o Sol nunca se punha no Egito"],c:1,e:"A terra parecia morrer na seca e renascer com a cheia. Osíris simbolizava esse ciclo de morrer e voltar à vida. 🌾"},
{n:"d",t:"Deuses do Nilo",q:"Por que a religião egípcia estava tão ligada ao rio Nilo?",a:["Porque o rio era a fonte de água, alimento e sobrevivência do povo","Porque no rio moravam os faraós","Porque o rio separava o Egito da Ásia","Porque era proibido navegar no rio"],c:0,e:"Tudo dependia do Nilo: comida, água, transporte. O que é essencial para a vida acaba virando sagrado."},
{n:"d",t:"Deuses do Nilo",q:"Os sacerdotes tinham grande poder na sociedade egípcia porque:",a:["comandavam o exército nas guerras","cuidavam dos templos e dos rituais, intermediando o povo e os deuses","plantavam a maior parte dos alimentos","construíam sozinhos as pirâmides"],c:1,e:"Quem falava com os deuses tinha prestígio e influência. Por isso os sacerdotes ficavam logo abaixo do faraó."},
{n:"d",t:"Deuses do Nilo",q:"O faraó era considerado um deus vivo. Qual consequência isso trazia?",a:["Suas ordens tinham caráter sagrado e não podiam ser contestadas","Ele era proibido de governar","Ele precisava ser eleito pelo povo","Ele não podia entrar nos templos"],c:0,e:"Se o rei é um deus, desobedecer a ele é desobedecer à religião. Isso tornava o poder do faraó praticamente absoluto."},
{n:"d",t:"Deuses do Nilo",q:"Hórus era representado como um falcão e associado ao céu e à realeza. Por isso, o faraó era visto como:",a:["um servo de Hórus, sem poder","a manifestação de Hórus na Terra","inimigo de Hórus","um sacerdote comum de Hórus"],c:1,e:"Os egípcios acreditavam que o faraó vivo era Hórus na Terra. Isso reforçava sua autoridade sobre todos. 🦅"},
{n:"d",t:"Deuses do Nilo",q:"Ao comparar a religião egípcia com a religião hebraica antiga, uma diferença central é que:",a:["os egípcios eram politeístas e os hebreus, monoteístas","ambos adoravam exatamente os mesmos deuses","os egípcios não tinham templos","os hebreus adoravam o faraó"],c:0,e:"Egípcios cultuavam muitos deuses; os hebreus foram um dos primeiros povos a cultuar um único Deus."},
{n:"d",t:"Deuses do Nilo",q:"As oferendas deixadas nos templos egípcios tinham a função de:",a:["pagar impostos ao faraó","agradar aos deuses e pedir proteção e boas colheitas","alimentar os animais sagrados do deserto","decorar as casas dos camponeses"],c:1,e:"Comida, bebida e objetos eram ofertados em troca de proteção divina, sobretudo para garantir boas cheias e colheitas."},
{n:"d",t:"Deuses do Nilo",q:"Por que era comum um mesmo deus egípcio ter versões e importâncias diferentes conforme a região e a época?",a:["Porque a religião mudava por decisão do povo em votação","Porque o Egito era grande e a crença foi se transformando ao longo de milhares de anos","Porque os deuses eram esquecidos a cada ano","Porque só existia um único templo no Egito"],c:1,e:"A civilização egípcia durou milhares de anos. Nesse tempão, cada região deu seus próprios significados aos deuses."},
{n:"d",t:"Escrita hieroglífica",q:"A escrita hieroglífica era formada por:",a:["letras iguais às do nosso alfabeto","sinais e desenhos que representavam sons, objetos ou ideias","apenas números","cunhas marcadas em argila mole"],c:1,e:"Hieróglifos são desenhos-símbolos. Cuidado: as cunhas em argila eram a escrita cuneiforme, dos mesopotâmicos."},
{n:"d",t:"Escrita hieroglífica",q:"Qual era a principal diferença entre a escrita hieroglífica egípcia e a escrita cuneiforme mesopotâmica?",a:["a hieroglífica usava desenhos-símbolos; a cuneiforme usava marcas em forma de cunha na argila","as duas eram idênticas","a hieroglífica usava o nosso alfabeto","a cuneiforme era feita apenas em papiro"],c:0,e:"Egito: desenhos gravados ou pintados, muito em papiro e pedra. Mesopotâmia: cunhas apertadas em placas de argila."},
{n:"d",t:"Escrita hieroglífica",q:"Por que os escribas tinham posição privilegiada na sociedade egípcia?",a:["porque eram os únicos que podiam falar com o faraó","porque dominavam a leitura e a escrita, habilidades raras e essenciais","porque eram os mais fortes fisicamente","porque não precisavam obedecer às leis"],c:1,e:"Quase ninguém sabia escrever. Quem registrava impostos, colheitas e leis se tornava indispensável ao governo. ✍️"},
{n:"d",t:"Escrita hieroglífica",q:"O papiro foi importante para o Egito porque:",a:["servia como material leve para registrar textos, funcionando como nosso papel","era usado para construir pirâmides","substituía a comida em épocas de seca","servia de moeda em todo o Mediterrâneo"],c:0,e:"Feito de uma planta das margens do Nilo, o papiro permitia guardar e transportar textos com facilidade. 📜"},
{n:"d",t:"Escrita hieroglífica",q:"A Pedra de Roseta foi fundamental para os estudiosos porque:",a:["continha o mesmo texto em escritas diferentes, permitindo decifrar os hieróglifos","era feita de ouro maciço","guardava o corpo de um faraó","mostrava o mapa completo do Egito"],c:0,e:"Como o texto se repetia em grego (língua conhecida) e em hieróglifos, foi possível comparar e decifrar. Champollion liderou essa descoberta. 🔍"},
{n:"d",t:"Escrita hieroglífica",q:"Boa parte dos hieróglifos que conhecemos foi encontrada em templos e tumbas. O que isso indica sobre o uso dessa escrita?",a:["que ela era usada apenas para brincadeiras","que tinha forte caráter sagrado e ligado à religião e ao poder","que ninguém a usava no Egito","que era usada só por crianças na escola"],c:1,e:"Hieróglifo significa algo como 'escrita sagrada'. Ela registrava orações, feitos dos faraós e textos religiosos."},
{n:"d",t:"Escrita hieroglífica",q:"Por que a escrita foi importante para a organização do Estado egípcio?",a:["porque permitia registrar impostos, estoques de grãos, leis e ordens do faraó","porque servia apenas para escrever poemas de amor","porque impedia a construção de templos","porque substituía o trabalho dos camponeses"],c:0,e:"Governar um território enorme exige controle. Sem registros escritos, seria impossível cobrar impostos e administrar as colheitas."},
{n:"d",t:"Escrita hieroglífica",q:"Um estudante afirma: 'Todos os egípcios sabiam ler hieróglifos'. Essa afirmação está:",a:["correta, pois havia escolas para todos","incorreta, pois a leitura e a escrita eram domínio de poucos, sobretudo escribas e sacerdotes","correta, pois os hieróglifos eram muito simples","incorreta, pois ninguém sabia ler no Egito"],c:1,e:"A maioria era formada por camponeses que trabalhavam na terra e não estudavam. Escrever era privilégio de poucos."},
{n:"d",t:"Escrita hieroglífica",q:"Os escribas passavam anos estudando. Isso mostra que, no Egito, a escrita:",a:["era considerada uma habilidade simples","exigia longa formação e por isso dava status a quem a dominava","podia ser aprendida em poucos dias","era proibida por lei"],c:1,e:"Eram centenas de sinais para memorizar. Quanto mais difícil e raro o conhecimento, mais valorizado ficava quem o tinha."},
{n:"d",t:"Escrita hieroglífica",q:"Comparando o alfabeto fenício com os hieróglifos, pode-se dizer que o alfabeto fenício:",a:["era mais simples, com poucas letras, o que facilitava aprender","tinha mais sinais que os hieróglifos","era feito apenas com desenhos de animais","nunca foi usado para o comércio"],c:0,e:"Com cerca de 22 sinais, o alfabeto fenício era muito mais fácil de aprender — ótimo para comerciantes com pressa."},
{n:"d",t:"Escrita hieroglífica",q:"Por que muitos monumentos egípcios traziam o nome do faraó escrito em hieróglifos?",a:["para ensinar as crianças a ler","para registrar e eternizar seus feitos e seu poder","porque era proibido escrever nomes de pessoas comuns em papiro","para marcar o preço da construção"],c:1,e:"Escrever o nome era uma forma de garantir que o faraó fosse lembrado para sempre — uma espécie de eternidade em pedra."},
{n:"d",t:"Mumificação",q:"A mumificação estava diretamente ligada à crença egípcia de que:",a:["o corpo deveria ser destruído após a morte","havia vida após a morte e a alma precisaria do corpo preservado","os mortos voltavam como animais","não existia nada depois da morte"],c:1,e:"Para os egípcios, a alma retornaria ao corpo. Se o corpo apodrecesse, essa volta seria impossível."},
{n:"d",t:"Mumificação",q:"Durante a mumificação, os órgãos internos eram retirados principalmente porque:",a:["seriam vendidos no comércio","apodreceriam rapidamente e estragariam o corpo","eram considerados sem valor nenhum","atrapalhavam o transporte do corpo"],c:1,e:"Os órgãos se decompõem primeiro. Retirando-os, o corpo se conservava por muito mais tempo."},
{n:"d",t:"Mumificação",q:"Os vasos canópicos serviam para:",a:["guardar os órgãos retirados do corpo durante a mumificação","armazenar água para as cheias","guardar joias do faraó vivo","transportar tijolos de barro"],c:0,e:"Cada vaso guardava um órgão e era protegido por uma divindade. Só o coração costumava ficar no corpo."},
{n:"d",t:"Mumificação",q:"O natrão, uma espécie de sal, era usado na mumificação para:",a:["dar cor dourada ao corpo","secar o corpo, retirando a umidade","perfumar as tumbas","colar as faixas de linho"],c:1,e:"Sem água, os micro-organismos não conseguem agir. O natrão secava o corpo, e por isso ele não se decompunha."},
{n:"d",t:"Mumificação",q:"Objetos, comida e até móveis eram enterrados junto com o morto porque os egípcios acreditavam que:",a:["esses itens seriam úteis na vida após a morte","era proibido guardar objetos em casa","os ladrões não roubariam tumbas","os objetos pertenciam aos sacerdotes"],c:0,e:"A vida após a morte era pensada como continuação desta vida. Então o morto levava o que precisaria por lá."},
{n:"d",t:"Mumificação",q:"As pirâmides de Gizé foram construídas principalmente para servir como:",a:["moradias dos camponeses","túmulos monumentais de faraós","celeiros de trigo","fortalezas militares"],c:1,e:"Quéops, Quéfren e Miquerinos foram sepultados ali. A pirâmide era a casa eterna do faraó. 🔺"},
{n:"d",t:"Mumificação",q:"O que a existência de múmias muito bem preservadas nos permite descobrir hoje?",a:["apenas o nome dos faraós","informações sobre alimentação, doenças e costumes dos antigos egípcios","o valor exato do ouro no Egito","a localização de todos os templos perdidos"],c:1,e:"Estudando as múmias, cientistas descobrem o que aquelas pessoas comiam, de que adoeciam e como viviam. 🔬"},
{n:"d",t:"Mumificação",q:"Por que nem todos os egípcios eram mumificados com o mesmo cuidado?",a:["porque a mumificação completa era cara e reservada a faraós e pessoas ricas","porque era proibida para adultos","porque só mulheres podiam ser mumificadas","porque ninguém queria ser mumificado"],c:0,e:"Havia versões mais simples e baratas. Quanto mais rica a família, mais caprichado (e caro) era o processo."},
{n:"d",t:"Mumificação",q:"A construção das pirâmides exigiu muitos trabalhadores, planejamento e conhecimento de matemática. Isso mostra que os egípcios:",a:["tinham uma sociedade organizada, com conhecimentos avançados para a época","viviam isolados e sem organização","não sabiam contar","construíam sem nenhum plano"],c:0,e:"Erguer aquelas montanhas de pedra exigia cálculo, engenharia e milhares de pessoas coordenadas. Sinal de um Estado forte."},
{n:"d",t:"Mumificação",q:"O sarcófago tinha como função:",a:["abrigar e proteger o corpo mumificado","guardar grãos da colheita","servir de barco no rio Nilo","medir o nível das cheias"],c:0,e:"Era o caixão decorado, muitas vezes com o rosto do morto pintado, protegendo a múmia dentro da tumba."},
{n:"d",t:"Mumificação",q:"A preocupação egípcia com a vida após a morte explica principalmente:",a:["a existência de múmias, tumbas ricas, pirâmides e rituais funerários","a ausência total de templos no Egito","o fim da agricultura às margens do Nilo","a proibição da escrita hieroglífica"],c:0,e:"Tudo isso — múmias, tumbas, oferendas, pirâmides — nasce da mesma ideia: a morte é uma passagem, não um fim."},
{n:"d",t:"Mumificação",q:"Um arqueólogo encontra uma tumba com múmia, vasos canópicos, joias e alimentos. Que conclusão é mais adequada?",a:["a tumba pertencia a alguém de posição social elevada","a tumba era de um camponês pobre","os egípcios não acreditavam em vida após a morte","a múmia foi feita nos dias de hoje"],c:0,e:"Riqueza de objetos e mumificação caprichada indicam alguém importante — faraó, sacerdote ou nobre."},
{n:"d",t:"Mumificação",q:"Por que o clima seco do deserto egípcio ajudou na conservação das múmias e dos objetos das tumbas?",a:["porque a falta de umidade retarda a decomposição","porque o calor derretia os corpos","porque chovia todos os dias","porque a areia era feita de sal puro"],c:0,e:"Umidade é o que estraga tudo. No deserto seco, corpos, papiros e madeiras se conservaram por milhares de anos. 🏜️"}
];
